//! Where the palette can come from. On an end-4 / end4-pC desktop the shell
//! renders its Material colors with matugen; the file manager has its own
//! `theme.json`. Both use the same role names, so either can be loaded.

use std::path::PathBuf;

/// Colors generated by illogical-impulse / end4-pC (matugen output).
pub fn end4_colors_path() -> Option<PathBuf> {
    dirs::state_dir().map(|d| d.join("quickshell/user/generated/colors.json"))
}

/// The Material 3 File Manager's matugen output.
pub fn file_manager_theme_path() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join("material_3_file_manager/theme.json"))
}

/// First palette file that exists, in priority order.
pub fn auto_theme_path() -> Option<PathBuf> {
    [end4_colors_path(), file_manager_theme_path()]
        .into_iter()
        .flatten()
        .find(|p| p.is_file())
}
